<script setup>
import { router, useForm } from '@inertiajs/vue3'
import PortalLayout from '@/Layouts/PortalLayout.vue'
const props=defineProps({doctor:Object,clinics:Array,suppliers:Array,inventory:Array,quotes:Array,orders:Array,orderItems:Array,canManage:Boolean,canApprove:Boolean})
const supplierForm=useForm({clinic_id:'',name:'',contact_name:'',phone:'',email:'',tax_id:'',address:'',notes:''})
const quoteForm=useForm({clinic_id:props.clinics?.[0]?.id??'',supplier_id:'',inventory_item_id:'',minimum_quantity:1,unit_cost_rial:0,lead_time_days:0,valid_until:'',notes:''})
const money=v=>new Intl.NumberFormat('fa-IR').format(Number(v||0))+' ریال'
const num=v=>new Intl.NumberFormat('fa-IR').format(Number(v||0))
const saveSupplier=()=>supplierForm.post(route('portal.procurement.suppliers.store'),{onSuccess:()=>supplierForm.reset('name','contact_name','phone','email','tax_id','address','notes')})
const saveQuote=()=>quoteForm.post(route('portal.procurement.quotes.store'),{onSuccess:()=>quoteForm.reset('minimum_quantity','unit_cost_rial','lead_time_days','valid_until','notes')})
const orderFromQuote=q=>{const quantity=window.prompt('مقدار موردنیاز ('+q.unit+')',String(q.minimum_quantity));if(quantity===null)return;router.post(route('portal.procurement.quotes.order',q.id),{quantity:Number(quantity)})}
const receive=line=>{const remaining=Number(line.ordered_quantity)-Number(line.received_quantity);const quantity=window.prompt('مقدار دریافتی؛ حداکثر '+remaining,String(remaining));if(quantity===null)return;router.post(route('portal.procurement.orders.items.receive',{order:line.purchase_order_id,item:line.id}),{quantity:Number(quantity)})}
const status=s=>({draft:'پیش‌نویس',approved:'تأییدشده',partially_received:'دریافت ناقص',received:'کامل دریافت‌شده',cancelled:'لغوشده'})[s]||s
</script>
<template><PortalLayout :doctor="doctor"><main dir="rtl" class="mx-auto max-w-7xl space-y-5 p-3 sm:p-5">
<header class="rounded-3xl bg-gradient-to-l from-slate-950 to-teal-800 p-6 text-white"><p class="text-xs font-bold text-teal-200">PRONEEX · PROCUREMENT</p><h1 class="mt-2 text-2xl font-black">تدارکات هوشمند کلینیک</h1><p class="mt-2 text-sm text-white/80">مدیریت تأمین‌کنندگان، مقایسه قیمت، سفارش خرید و ورود کنترل‌شده کالا به انبار.</p></header>
<section v-if="canManage" class="grid gap-4 lg:grid-cols-2">
<article class="rounded-2xl border bg-white p-4"><h2 class="mb-3 font-black">ثبت تأمین‌کننده</h2><form @submit.prevent="saveSupplier" class="grid gap-2 sm:grid-cols-2"><input v-model="supplierForm.name" required placeholder="نام شرکت / فروشنده" class="rounded-xl border-slate-300 text-sm sm:col-span-2"><input v-model="supplierForm.contact_name" placeholder="نام رابط" class="rounded-xl border-slate-300 text-sm"><input v-model="supplierForm.phone" placeholder="تلفن" class="rounded-xl border-slate-300 text-sm"><input v-model="supplierForm.email" type="email" placeholder="ایمیل" class="rounded-xl border-slate-300 text-sm"><input v-model="supplierForm.tax_id" placeholder="شناسه ملی / اقتصادی" class="rounded-xl border-slate-300 text-sm"><select v-model="supplierForm.clinic_id" class="rounded-xl border-slate-300 text-sm"><option value="">تأمین‌کننده مشترک همه شعب</option><option v-for="c in clinics" :key="c.id" :value="c.id">{{c.name}}</option></select><input v-model="supplierForm.address" placeholder="نشانی" class="rounded-xl border-slate-300 text-sm"><button :disabled="supplierForm.processing" class="rounded-xl bg-teal-700 p-3 text-sm font-bold text-white sm:col-span-2">ثبت تأمین‌کننده</button></form></article>
<article class="rounded-2xl border bg-white p-4"><h2 class="mb-3 font-black">ثبت پیشنهاد قیمت تأمین‌کننده</h2><form @submit.prevent="saveQuote" class="grid gap-2 sm:grid-cols-2"><select v-model="quoteForm.clinic_id" required class="rounded-xl border-slate-300 text-sm"><option v-for="c in clinics" :key="c.id" :value="c.id">{{c.name}}</option></select><select v-model="quoteForm.supplier_id" required class="rounded-xl border-slate-300 text-sm"><option value="">تأمین‌کننده</option><option v-for="s in suppliers.filter(x=>!x.clinic_id||String(x.clinic_id)===String(quoteForm.clinic_id))" :key="s.id" :value="s.id">{{s.name}}</option></select><select v-model="quoteForm.inventory_item_id" required class="rounded-xl border-slate-300 text-sm sm:col-span-2"><option value="">انتخاب کالا از انبار شعبه</option><option v-for="i in inventory.filter(x=>String(x.clinic_id)===String(quoteForm.clinic_id))" :key="i.id" :value="i.id">{{i.name}} · {{i.unit}}</option></select><input v-model.number="quoteForm.unit_cost_rial" type="number" min="0" required placeholder="قیمت هر واحد (ریال)" class="rounded-xl border-slate-300 text-sm"><input v-model.number="quoteForm.minimum_quantity" type="number" min="0.001" step="0.001" required placeholder="حداقل مقدار سفارش" class="rounded-xl border-slate-300 text-sm"><input v-model.number="quoteForm.lead_time_days" type="number" min="0" placeholder="زمان تحویل (روز)" class="rounded-xl border-slate-300 text-sm"><input v-model="quoteForm.valid_until" type="date" class="rounded-xl border-slate-300 text-sm"><button :disabled="quoteForm.processing" class="rounded-xl bg-slate-900 p-3 text-sm font-bold text-white sm:col-span-2">ثبت پیشنهاد و مقایسه</button></form></article>
</section>
<section class="rounded-2xl border bg-white p-4"><h2 class="font-black">مقایسه پیشنهادهای معتبر</h2><p class="mt-1 text-xs text-slate-500">پیشنهادها بر اساس قیمت واحد مرتب شده‌اند؛ زمان تحویل و حداقل سفارش نیز قابل مقایسه است.</p><div class="mt-3 overflow-x-auto"><table class="w-full min-w-[700px] text-right text-xs"><thead class="bg-slate-50"><tr><th class="p-3">کالا</th><th class="p-3">تأمین‌کننده</th><th class="p-3">قیمت واحد</th><th class="p-3">حداقل سفارش</th><th class="p-3">تحویل</th><th class="p-3">اعتبار تا</th><th class="p-3">اقدام</th></tr></thead><tbody><tr v-for="q in quotes" :key="q.id" class="border-t"><td class="p-3 font-bold">{{q.item_name}} ({{q.unit}})</td><td class="p-3">{{q.supplier_name}}</td><td class="p-3 font-bold text-teal-700">{{money(q.unit_cost_rial)}}</td><td class="p-3">{{num(q.minimum_quantity)}}</td><td class="p-3">{{num(q.lead_time_days)}} روز</td><td class="p-3">{{q.valid_until||'بدون تاریخ'}}</td><td class="p-3"><button v-if="canManage" @click="orderFromQuote(q)" class="rounded-lg bg-teal-700 px-3 py-2 text-white">ایجاد سفارش</button></td></tr><tr v-if="!quotes.length"><td colspan="7" class="p-6 text-center text-slate-400">هنوز پیشنهاد قیمت معتبری ثبت نشده است.</td></tr></tbody></table></div></section>
<section class="rounded-2xl border bg-white p-4"><h2 class="font-black">سفارش‌های خرید و دریافت کالا</h2><div v-for="o in orders" :key="o.id" class="mt-3 rounded-xl border p-3"><div class="flex flex-wrap items-center justify-between gap-2"><div><b>{{o.order_number}} · {{o.supplier_name}}</b><p class="text-xs text-slate-500">{{clinics.find(c=>c.id===o.clinic_id)?.name}} · {{money(o.total_amount_rial)}}</p></div><div class="flex items-center gap-2"><span class="rounded-full bg-slate-100 px-3 py-1 text-xs">{{status(o.status)}}</span><button v-if="canApprove&&o.status==='draft'" @click="router.patch(route('portal.procurement.orders.approve',o.id))" class="rounded-lg bg-amber-600 px-3 py-2 text-xs font-bold text-white">تأیید سفارش</button></div></div><div v-for="line in orderItems.filter(x=>x.purchase_order_id===o.id)" :key="line.id" class="mt-2 flex flex-wrap items-center justify-between gap-2 rounded-lg bg-slate-50 p-3 text-xs"><div><b>{{line.item_name}}</b><p class="text-slate-500">سفارش {{num(line.ordered_quantity)}} · دریافت {{num(line.received_quantity)}} {{line.unit}} · {{money(line.unit_cost_rial)}} / واحد</p></div><button v-if="canManage&&['approved','partially_received'].includes(o.status)&&Number(line.received_quantity)<Number(line.ordered_quantity)" @click="receive(line)" class="rounded-lg bg-teal-700 px-3 py-2 font-bold text-white">ثبت دریافت</button></div></div><p v-if="!orders.length" class="py-6 text-center text-xs text-slate-400">سفارشی ثبت نشده است.</p></section>
<section class="rounded-2xl border border-amber-200 bg-amber-50 p-4 text-xs leading-6 text-amber-950"><b>کنترل‌های مالی و انبار</b><p>ثبت پیشنهاد به‌تنهایی موجودی را تغییر نمی‌دهد. سفارش ابتدا به‌صورت پیش‌نویس ایجاد و فقط توسط پزشک/مدیر تأیید می‌شود. دریافت جزئی یا کامل، با قفل تراکنشی، کنترل مقدار باقیمانده، میانگین موزون بهای موجودی و گردش انبار/حسابداری ثبت می‌شود. پرداخت به فروشنده در این نسخه خودکار نیست و باید در فرآیند مالی جداگانه تسویه شود.</p></section>
</main></PortalLayout></template>
